// --- Main Init Function ---
function init() {
    const canvas = document.getElementById('coin-hero');
    const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');

    if (!gl) { alert("WebGL not supported"); return; }

    // Compile Program
    const program = createProgram(gl, VS_SOURCE, FS_SOURCE);

    // Buffers (We will generate one big buffer for all parts: Front Face, Back Face, Side Wall). 
