    // To avoid complexity of texture switching inside the same pass: Use separate VBOs in JS loops or manage attribute bindings? 
    // Let's just create 3 independent buffers for simplicity and robustness (Front, Back, Side).

    const coinThickness = 10; // In "units"

    // Generate Textures via Canvas API

    // Helper to draw emblem/text onto canvas texture
    function generateTexture(contentFn) {
        const tCvs = document.createElement('canvas');
        tCvs.width = 512; tCvs.height = 512;
