        drawStar(ctx, w/2, w/2 - 60, 5, 80, 40);
    });

    // Back Texture: Denomination "10,000 TOKENS"
    const backTexCanvas = generateTexture((ctx, w) => {
        ctx.font = 'bold 80px sans-serif';
        ctx.fillStyle = '#fff';
        ctx.textAlign = 'center';
